import {GameSession} from './engine.js';
import {LocalTransport} from './transport.js';
import {questions} from './questions.js';
import {tiles} from './combo.js';
const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let transport,state,timer,deadline,selected=-1,busy=false,version=0;
let pulse=()=>{};
import('./field.js').then(m=>pulse=m.pulse).catch(()=>{});
const phaseNames={ready:'ПОДГОТОВКА',quiz:'БИТКА',result:'РЕЗУЛТАТ',market:'МАГАЗИН',reveal:'РАЗКРИВАНЕ',finished:'ФИНАЛ'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function tileHtml(t){const x=tiles.find(x=>x.id===t.id);return `<span class="tile-icon">${x.icon}</span><div><b>${x.name}</b><p>${x.desc}${t.topic?' · '+escape(t.topic):''}</p></div>`;}
function slots(s,empty=false){const active=s.players[0].tiles;return `<div class="loadout ${active.length?'':'is-empty'}"><div class="eyebrow">ТВОЯТА КОМБИНАЦИЯ <span>${active.length} / 3</span></div><div class="slots">${(empty?[0,1,2]:active.map((_,i)=>i)).map(i=>active[i]?`<div class="slot" data-motion>${tileHtml(active[i])}</div>`:`<div class="slot empty" data-motion><span>＋</span><b>Слот 0${i+1}</b><p>Тук започва комбинацията ти</p></div>`).join('')}</div>${!active.length&&!empty?'<p class="empty-hint">Първата ти плочка те очаква в магазина.</p>':''}</div>`;}
function send(action){if(busy)return;pulse();transport.send(action);}
function boot(){clearInterval(timer);transport?.close();transport=new LocalTransport(new GameSession());transport.subscribe(render);}
function time(seconds,expire){clearInterval(timer);deadline=Date.now()+seconds*1000;const tick=()=>{const remaining=Math.max(0,deadline-Date.now()),left=Math.ceil(remaining/1000);if($('#timer'))$('#timer').textContent=left;if($('#bar'))$('#bar').style.transform=`scaleX(${remaining/(seconds*1000)})`;if($('#countdown'))$('#countdown').textContent=left;if(!remaining){clearInterval(timer);expire();}};timer=setInterval(tick,100);tick();}
function animateIn(){const elements=[...$('#stage').querySelectorAll('[data-motion]')];if(reduced.matches)return Promise.resolve();return Promise.all(elements.map((el,i)=>el.animate([{opacity:0,transform:'translateY(18px) scale(.94)',filter:'blur(4px)'},{opacity:1,transform:'translateY(0) scale(1)',filter:'blur(0)'}],{duration:550,delay:Math.min(i*45,270),easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'}).finished.catch(()=>{})));}
async function render(s){const current=++version;clearInterval(timer);busy=true;$('#stage').inert=true;
 if(state&&!reduced.matches){pulse(1.2);await Promise.all([...$('#stage').querySelectorAll('[data-motion]')].map((el,i)=>el.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'translateY(-8px) scale(.9)'}],{duration:220,delay:Math.min(i*18,100),easing:'cubic-bezier(.55,0,1,.45)',fill:'forwards'}).finished.catch(()=>{})));}
 if(current!==version)return;
 state=s;const q=questions[s.round-1],me=s.players[0];
 document.body.dataset.phase=s.phase;
 $('#phase-label').textContent=phaseNames[s.phase];$('#round-label').textContent=`РУНД ${String(s.round).padStart(2,'0')} / 08`;
 $('#rounds').innerHTML=questions.map((x,i)=>`<span class="round ${i+1===s.round?'active':i+1<s.round?'done':''}" title="Рунд ${i+1}: ${x.topic}" ${i+1===s.round?'aria-current="step"':''}></span>`).join('');
 updateScores(s.phase==='result'?s.players.map((p,i)=>({...p,score:p.score-s.rewards[i].points,credits:p.credits-s.rewards[i].credits})):s.players);
 $('#rival').textContent='NOVA / '+(s.players[1].tiles.map(t=>tiles.find(x=>x.id===t.id).name).join(' · ')||'няма плочки');
 const stage=$('#stage'),top=label=>`<div class="stage-top" data-motion><span class="eyebrow">${label}</span><span class="tag">${q.topic}</span></div>`;
 if(s.phase==='ready'){
 stage.innerHTML=`${top(s.round===1?'ТВОЯТ СЛЕДВАЩ ХОД':'НОВ РУНД')}<div class="intro" data-motion><div class="hero-symbol" aria-hidden="true">✳</div><h1>${s.round===1?'Знанието е само<br><em>началото.</em>':'Нова тема.<br><em>Нови възможности.</em>'}</h1><p>${s.round===1?'Отговаряй. Наддавай. Комбинирай.<br>Изгради своята победа срещу NOVA.':`На ход е <strong>${q.topic}</strong>. ${s.round>6?'Без пазар — нека комбинацията ти работи.':'Всеки верен отговор отваря нови възможности.'}`}</p></div>${slots(s,true)}<div class="ready-actions" data-motion>${me.tiles.some(t=>t.id==='converter')?'<label class="convert"><input id="convert" type="checkbox"> Конвертор: 2 кредита → +1 точка при верен отговор</label>':''}<button class="primary" id="start">${s.round===1?'Започни дуела':'Отвори въпроса'} <span>↗</span></button><small>25 СЕКУНДИ · БЕЗ БОНУС ЗА БЪРЗИНА</small></div>`;
 $('#start').onclick=()=>{if(busy)return;if(s.round===1)enterFullscreen();send({type:'start',convert:$('#convert')?.checked});};
 }
 if(s.phase==='quiz'){
 stage.innerHTML=`${top('СЛЕДВАЙ ИНСТИНКТА СИ')}<div class="battle-loadout">${slots(s)}</div><div class="question-dock"><div class="question-clock" data-motion><span id="timer">25</span><small>СЕКУНДИ</small></div><div class="question-card" data-motion><span class="question-number">ВЪПРОС / ${String(s.round).padStart(2,'0')}</span><h2>${q.text}</h2></div><div class="answers">${q.answers.map((a,i)=>`<button class="answer" data-motion data-answer="${i}"><span class="answer-letter">${'ABCD'[i]}</span><b>${a}</b><span class="answer-shortcut">${i+1}</span></button>`).join('')}</div><div class="progress" aria-hidden="true"><i id="bar"></i></div><div class="question-foot" data-motion><span>ЕДИН ВЕРЕН ОТГОВОР</span><span>КЛАВИШИ 1 — 4</span></div></div>`;
 stage.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>send({type:'answer',answer:Number(b.dataset.answer)}));
 }
 if(s.phase==='result'){
 stage.innerHTML=`${top('МОМЕНТЪТ НА ИСТИНАТА')}<div class="result-heading" data-motion><h2>Два избора. Един отговор.</h2><p id="reveal-status" role="status">Разкриваме отговорите…</p></div><div class="result-players">${s.players.map((p,i)=>`<article class="result-player ${i?'nova':'you'}" data-motion><span class="avatar">${i?'✧':'⌁'}</span><b>${p.name}</b><div class="answer-verdict" data-verdict="${i}">Изборът е заключен</div><div class="reward" data-reward="${i}">•••</div><small class="reward-details" data-details="${i}"></small></article>`).join('')}</div><div class="result-question" data-motion><span class="question-number">ВЪПРОС / ${String(s.round).padStart(2,'0')}</span><h2>${q.text}</h2></div><div class="answers result-answers">${q.answers.map((a,i)=>`<div class="answer result-answer" data-motion data-result-answer="${i}"><span class="answer-letter">${'ABCD'[i]}</span><b>${a}</b><span class="answer-owners"></span><span class="correct-label"></span></div>`).join('')}</div><div class="auto-next" data-motion><span>${s.round<7?'КЪМ МАГАЗИНА':s.round===8?'КЪМ ФИНАЛА':'СЛЕДВАЩ РУНД'}</span><span>след <b id="countdown">5</b> сек <span aria-hidden="true">→</span></span></div><div class="progress"><i id="bar"></i></div>`;
 }
 if(s.phase==='market'){
 selected=-1;stage.innerHTML=`${top('МАГАЗИН / ТАЙНО НАДДАВАНЕ')}<div class="shop-heading" data-motion><div><h2>Следващото ти предимство.</h2><p>Една плочка. Тайна оферта. Най-високата печели.</p></div><div class="wallet"><span>ТВОЯТ БЮДЖЕТ</span><b>◈ ${me.credits}</b><small>кредита</small></div></div><div class="market">${s.market.map((t,i)=>`<button class="shop-card" data-motion data-tile="${i}" aria-pressed="false" ${me.tiles.some(x=>x.id===t.id)||me.credits<1?'disabled':''}><span class="card-index">0${i+1} / ${me.tiles.some(x=>x.id===t.id)?'ПРИТЕЖАВАШ':'ПОДОБРЕНИЕ'}</span><b>${t.name}</b><small>${t.desc}</small><span class="shop-card-bottom"><span class="tile-icon">${t.icon}</span><span class="choose-label">ИЗБЕРИ ↗</span></span></button>`).join('')}<div class="shop-note" data-motion><span class="eyebrow">ЕДИН ХОД НАПРЕД</span><b>Силата е<br>в комбинацията.</b><p>До 3 различни плочки.<br>Покупките действат от следващия рунд. При равни оферти никой не плаща.</p><div class="mini-loadout">${me.tiles.map(t=>`<span title="${tiles.find(x=>x.id===t.id).name}">${tiles.find(x=>x.id===t.id).icon}</span>`).join('')||'<span>＋</span><span>＋</span><span>＋</span>'}</div></div></div><div class="shop-controls" data-motion><div class="bid-controls"><label>Оферта <span><input id="amount" aria-label="Оферта в кредити" type="number" min="1" max="${me.credits}" value="1" ${me.credits<1?'disabled':''}> ◈</span></label><label>Слот за замяна <select id="slot">${[0,1,2].map(i=>`<option value="${i}">${i+1} · ${me.tiles[i]?tiles.find(t=>t.id===me.tiles[i].id).name:'празен'}</option>`).join('')}</select></label><label id="focus-label" hidden>Тема <select id="focus">${[...new Set(questions.map(q=>q.topic))].map(t=>`<option>${t}</option>`).join('')}</select></label></div><div class="actions"><button class="primary" id="bid" disabled>Заключи офертата ↗</button><button id="skip" class="secondary">Пропусни →</button><div class="market-clock"><span id="timer">15</span><small>СЕК</small></div></div><p id="error" role="alert"></p><div class="progress"><i id="bar"></i></div></div>`;
 stage.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{if(busy)return;selected=Number(b.dataset.tile);stage.querySelectorAll('[data-tile]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#bid').disabled=false;$('#focus-label').hidden=s.market[selected].id!=='focus';pulse(.6);});
 $('#bid').onclick=()=>{const amount=Number($('#amount').value);if(!Number.isInteger(amount)||amount<1||amount>me.credits){$('#error').textContent='Избери цяла сума между 1 и '+me.credits+'.';return;}send({type:'bid',tile:selected,amount,slot:Number($('#slot').value),topic:$('#focus').value});};$('#skip').onclick=()=>send({type:'bid'});
 }
 if(s.phase==='reveal'){
 stage.innerHTML=`${top('ОФЕРТИТЕ СА ОТВОРЕНИ')}<div class="intro compact" data-motion><div class="hero-symbol">◇</div><h1>Нови плочки.<br><em>Нов потенциал.</em></h1><p>Покупките се активират в следващия рунд.</p></div><div class="purchase-results">${s.events.map(e=>`<div class="purchase-line" data-motion><span>↗</span>${e}</div>`).join('')}</div>${slots(s,true)}<div class="ready-actions" data-motion><button id="next" class="primary">Следващ рунд <span>→</span></button></div>`;$('#next').onclick=()=>send({type:'continue'});
 }
 if(s.phase==='finished'){
 const delta=me.score-s.players[1].score;stage.innerHTML=`${top('ОСЕМ РУНДА ПО-КЪСНО')}<div class="intro compact" data-motion><div class="hero-symbol">${delta>=0?'✳':'✧'}</div><h1>${delta>0?'Твоята комбинация<br><em>спечели.</em>':delta===0?'Достоен дуел.<br><em>Споделена победа.</em>':'Този дуел<br><em>е за NOVA.</em>'}</h1></div><div class="final-score" data-motion><div><span>ТИ</span><b>${me.score}</b></div><span>:</span><div class="nova"><span>NOVA</span><b>${s.players[1].score}</b></div></div>${slots(s)}<div class="ready-actions" data-motion><button class="primary" id="again">Още един дуел <span>↻</span></button><small>КРЕДИТИТЕ НЕ УЧАСТВАТ В КРАЙНИЯ РЕЗУЛТАТ</small></div>`;$('#again').onclick=boot;
 }
 await animateIn();if(current!==version)return;busy=false;stage.inert=false;
 if(s.phase==='quiz')time(25,()=>send({type:'answer',answer:null}));
 if(s.phase==='market')time(15,()=>send({type:'bid'}));
 if(s.phase==='result'){
 const revealAt=Date.now()+1000;
 time(5,()=>send({type:'continue'}));
 // Reveal and countdown share a clock, including after a background-tab pause.
 const resultTimer=timer;const revealTick=setInterval(()=>{if(current!==version||timer!==resultTimer){clearInterval(revealTick);return;}if(Date.now()>=revealAt){clearInterval(revealTick);revealAnswers(s,q);}},50);
 }
}
function updateScores(players){$('#scores').innerHTML=players.map((p,i)=>`<div class="player ${i?'nova':'you'}"><span class="avatar">${i?'✧':'⌁'}</span><div class="player-name">${p.name}<small>◈ ${p.credits} кредита</small></div><div class="points">${p.score}<small>ТОЧКИ</small></div></div>`).join('');}
function revealAnswers(s,q){
 updateScores(s.players);
 $('#reveal-status').textContent='Верният отговор е маркиран с ✓';pulse(.7);
 s.players.forEach((p,i)=>{const correct=s.answers[i]===q.correct,answer=s.answers[i];const verdict=$(`[data-verdict="${i}"]`);verdict.textContent=answer===null?'Без отговор':`${'ABCD'[answer]} · ${correct?'Верен отговор':'Грешен отговор'}`;verdict.classList.add(correct?'is-correct':'is-wrong');const reward=s.rewards[i];$(`[data-reward="${i}"]`).textContent=`+${reward.points} т. / ${reward.credits>=0?'+':''}${reward.credits} ◈`;$(`[data-details="${i}"]`).textContent=s.events[i].join(' · ');});
 document.querySelectorAll('[data-result-answer]').forEach(el=>{const a=Number(el.dataset.resultAnswer),owners=s.answers.map((answer,i)=>answer===a?i:-1).filter(i=>i>=0);el.classList.add('revealed');if(owners.length)el.classList.add(owners.length===2?'shared':owners[0]===0?'picked-you':'picked-nova');el.querySelector('.answer-owners').textContent=owners.map(i=>s.players[i].name).join(' + ');if(a===q.correct){el.classList.add('correct');el.querySelector('.correct-label').textContent='✓';el.setAttribute('aria-label',`${q.answers[a]} — верен отговор`);}});
 if(!reduced.matches)document.querySelectorAll('.reward,.answer-verdict,.reward-details').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(10px) scale(.94)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:650,delay:i%3*60,easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'}));
}
function updateFullscreen(){const full=!!document.fullscreenElement,b=$('#fullscreen');b.setAttribute('aria-label',full?'Изход от цял екран':'На цял екран');b.title=b.getAttribute('aria-label');b.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="${full?'M3 8h5V3m13 5h-5V3M8 21v-5H3m13 5v-5h5':'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5'}"/></svg>`;}
async function enterFullscreen(){if(document.fullscreenElement)return;try{await document.documentElement.requestFullscreen();}catch{$('#fullscreen-note').textContent='Режимът на цял екран не е разрешен от браузъра. Играта запълва наличния прозорец.';$('#fullscreen-note').hidden=false;setTimeout(()=>$('#fullscreen-note').hidden=true,4500);}}
$('#fullscreen').onclick=async()=>{if(document.fullscreenElement){try{await document.exitFullscreen();}catch{}}else await enterFullscreen();};document.addEventListener('fullscreenchange',updateFullscreen);updateFullscreen();
$('#rules').onclick=()=>$('#help').showModal();$('#close-help').onclick=$('#help-ok').onclick=()=>$('#help').close();
$('#restart').onclick=()=>{if(busy)return;if(state.round===1&&state.phase==='ready'||confirm('Да започнем нов мач? Текущият резултат ще се изчисти.'))boot();};
document.addEventListener('keydown',e=>{if($('#help').open||e.repeat||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const i='1234'.indexOf(e.key);if(state?.phase==='quiz'&&i>=0)send({type:'answer',answer:i});});boot();
